void battle_sprite_load_front(PokemonId species, u32 *dest) {
    if (species > NUM_POKEMON) species = MON_NONE;
    const u32 *source = s_front_sprites[species];
    for (u32 i = 0; i < BATTLE_SPRITE_WORDS; i++) dest[i] = source[i];
}

void battle_sprite_load_back(PokemonId species, u32 *dest) {
    if (species > NUM_POKEMON) species = MON_NONE;
    const u32 *source = s_back_sprites[species];
    for (u32 i = 0; i < BATTLE_SPRITE_WORDS; i++) dest[i] = source[i];
}
